import axios from 'axios';
import { sign } from 'crypto';

const axiosClient = axios.create({
    baseURL: process.env.NEXT_PUBLIC_API_URL || "http://localhost:1337/api",
    timeout: 20000,
    
});


// Register interceptors only when running in the browser (avoid server-side localStorage)
if (typeof window !== 'undefined') {
    // Add request interceptor
    axiosClient.interceptors.request.use(
        (config) => {
            const token = localStorage.getItem('authToken');
            if (token) {
                // preserve existing headers and add Authorization
                config.headers = { ...(config.headers as any), Authorization: `Bearer ${token}` };
            }
            return config;
        },
        (error) => Promise.reject(error)
    );

    // Add response interceptor
    axiosClient.interceptors.response.use(
        (response) => response,
        (error) => {
            if (error.response?.status === 401) {
                localStorage.removeItem('authToken');
            }
            return Promise.reject(error);
        }
    );
}

const getCategory = ()=> axiosClient.get('/categories');

const getSliders = ()=> axiosClient.get('/sliders?populate=*').then(resp =>{
return resp.data.data
}) ;

const getCategoryList = ()=> axiosClient.get('/categories?populate=*').then(resp=>{

    return resp.data.data
});

const getAllProducts = ()=> axiosClient.get('/products?populate=*').then(resp=>{

    return resp.data.data
});

const getProductByCategory =(category: string)=>axiosClient.get('/products?filters[categories][name][$in]=' +category+"&populate=*")
.then(resp=>{
    return resp.data.data
});

const registerUser=(username: string, email: string, password: string)=>axiosClient.post(
    "/auth/local/register",{
        username:username,
        email:email,
        password:password
    }
);

const signIn=(email: string, password:string)=>axiosClient.post(
    '/auth/local', {
        identifier:email,
        password:password
    }
);
const addToCart=(data:any, jwt:string)=>axiosClient.post('/user-carts', data, {
    headers:{
        Authorization:"Bearer "+jwt
    }
});

const getUserCartItems = (userId: number, jwt: string) => 
  axiosClient.get(
    `/user-carts?filters[userId][$eq]=${userId}&populate=*`,
    {
      headers: {
        Authorization: `Bearer ${jwt}`
      }
    }
  ).then(resp =>{
    return resp.data.data
  });

// Also add methods for cart management
const deleteCartItem = (documentId: string, jwt: string) =>
  axiosClient.delete(`/user-carts/${documentId}`, {
    headers: {
      Authorization: `Bearer ${jwt}`
    }
  });

const updateCartItem = (documentId: string, data: any, jwt: string) =>
  axiosClient.put(`/user-carts/${documentId}`, data, {
    headers: {
      Authorization: `Bearer ${jwt}`
    }
  });

export default {
  getCategory,
  getSliders, 
  getCategoryList,
  getAllProducts,
  getProductByCategory,
  registerUser,
  signIn,
  addToCart,
  getUserCartItems,
  deleteCartItem,
  updateCartItem
};